// NewCreateRequestBody builds the HTTP request body from the payload of the
// "create" endpoint of the "notes" service.
func NewCreateRequestBody(p *notes.CreatePayload) *CreateRequestBody {
	body := &CreateRequestBody{
		ID:       p.ID,
		Notebook: p.Notebook,
		Title:    p.Title,
		Body:     p.Body,
	}
	if p.Tags != nil {
		body.Tags = make([]string, len(p.Tags))
		for i, val := range p.Tags {
			body.Tags[i] = val
		}
	}
	return body
}

// NewUpdateRequestBody builds the HTTP request body from the payload of the
// "update" endpoint of the "notes" service.
func NewUpdateRequestBody(p *notes.UpdatePayload) *UpdateRequestBody {
	body := &UpdateRequestBody{
		Notebook: p.Notebook,
		Title:    p.Title,
		Body:     p.Body,
	}
	if p.Tags != nil {
		body.Tags = make([]string, len(p.Tags))
		for i, val := range p.Tags {
			body.Tags[i] = val
		}
	}
	return body
}

// NewMoveRequestBody builds the HTTP request body from the payload of the
// "move" endpoint of the "notes" service.
